            window.belchertownEnsureHighcharts = (function() {
                var highchartsCorePromise = null;

                function loadScript(src) {
                    return new Promise(function(resolve, reject) {
                        var existing = document.querySelector('script[src="' + src + '"]');
                        if (existing) {
                            if (existing.getAttribute("data-loaded") === "1") {
                                resolve();
                                return;
                            }
                            existing.addEventListener("load", function() {
                                existing.setAttribute("data-loaded", "1");
                                resolve();
                            }, {once: true});
                            existing.addEventListener("error", function() {
                                reject(new Error("Failed loading script: " + src));
                            }, {once: true});
                            return;
                        }

                        var script = document.createElement("script");
                        script.src = src;
                        script.async = false;
                        script.onload = function() {
                            script.setAttribute("data-loaded", "1");
                            resolve();
                        };
                        script.onerror = function() {
                            reject(new Error("Failed loading script: " + src));
                        };
                        document.head.appendChild(script);
                    });
                }

                return function() {
                    if (typeof Highcharts !== "undefined") {
                        return Promise.resolve(Highcharts);
                    }

                    if (highchartsCorePromise) {
                        return highchartsCorePromise;
                    }

                    highchartsCorePromise = loadScript("//code.highcharts.com/stock/12.6/highstock.js")
                        .then(function() {
                            return loadScript("//code.highcharts.com/12.6/highcharts-more.js");
                        })
                        .then(function() {
                            return Highcharts;
                        })
                        .catch(function(error) {
                            highchartsCorePromise = null;
                            throw error;
                        });

                    return highchartsCorePromise;
                };
            })();
