function mqtt_modal_normalized_text(value) {
    return belchertown_decode_html_entities(value)
        .replace(/\u00a0/g, " ")
        .replace(/\s+\/\s+/g, " / ")
        .replace(/\s+/g, " ")
        .trim();
}

function mqtt_packet_value_text(value) {
    if (value === null) {
        return "null";
    }
    if (typeof value === "undefined") {
        return "";
    }
    if (typeof value === "number" || typeof value === "boolean") {
        return String(value);
    }
    if (typeof value === "string") {
        return mqtt_modal_normalized_text(value);
    }

    try {
        return JSON.stringify(value);
    } catch (e) {
        return String(value);
    }
}

function mqtt_set_latest_packet_data(payload) {
    mqtt_latest_packet_rows = [];

