function mqtt_next_reconnect_delay_ms() {
    var delay_ms = mqtt_reconnect_initial_delay_ms * Math.pow(2, Math.min(mqtt_reconnect_attempt_count, 5));
    mqtt_reconnect_attempt_count++;
    return Math.min(delay_ms, mqtt_reconnect_max_delay_ms);
}

function mqtt_schedule_reconnect(reason, reset_backoff) {
    if (reset_backoff) {
        mqtt_reset_reconnect_backoff();
    }
    if (mqtt_reconnect_timeout) {
        belchertown_debug("MQTT: Reconnect already scheduled; skipping duplicate request");
        return;
    }

    var delay_ms = mqtt_next_reconnect_delay_ms();
    belchertown_debug("MQTT: Scheduling reconnect attempt " + mqtt_reconnect_attempt_count + " in " + delay_ms + " ms" + (reason ? " after " + reason : ""));
    mqtt_reconnect_timeout = setTimeout(function() {
        mqtt_reconnect_timeout = null;
        if (mqtt_safe_client_connected()) {
            belchertown_debug("MQTT: Reconnect skipped because client is already connected");
            mqtt_reset_reconnect_backoff();
            return;
        }
        connect();
    }, delay_ms);
}

