function to_radians(degrees) {
    var value = parseFloat(degrees);
    if (!isFinite(value)) {
        return null;
    }
    return value * Math.PI / 180;
}

function moon_illumination_fraction(moonData) {
    var fullness = parseFloat(moonData && moonData["moon_fullness"]);
    if (!isFinite(fullness)) {
        return null;
    }
    return Math.max(0, Math.min(1, fullness / 100));
}

function moon_tilt_template_degrees() {
    var tilt = parseFloat(moon_tilt_template_value);
    if (!isFinite(tilt)) {
        return null;
    }
    return tilt;
}

function moon_tilt_to_icon_rotation(tiltDegrees) {
    var tilt = parseFloat(tiltDegrees);
    if (!isFinite(tilt)) {
        return null;
    }

    // Skyfield moon_tilt uses the opposite sign convention from our SVG
    // screen-space rotation, so flip sign for display.
    return -tilt;
}

function moon_full_disc_path(cx, cy, r) {
    return "M " + cx + " " + (cy - r) +
        " A " + r + " " + r + " 0 1 1 " + cx + " " + (cy + r) +
        " A " + r + " " + r + " 0 1 1 " + cx + " " + (cy - r) + " Z";
}

function moon_crescent_path(cx, cy, r, rx, brightOnRight) {
    if (brightOnRight) {
        return "M " + cx + " " + (cy - r) +
            " A " + r + " " + r + " 0 0 1 " + cx + " " + (cy + r) +
            " A " + rx + " " + r + " 0 0 0 " + cx + " " + (cy - r) + " Z";
    }

    return "M " + cx + " " + (cy - r) +
        " A " + r + " " + r + " 0 0 0 " + cx + " " + (cy + r) +
        " A " + rx + " " + r + " 0 0 1 " + cx + " " + (cy - r) + " Z";
}

function moon_illuminated_path(fraction, waxing, cx, cy, r) {
    var k = Math.max(0, Math.min(1, fraction));

    if (k <= 0) {
        return "";
    }
    if (k >= 1) {
        return moon_full_disc_path(cx, cy, r);
    }

    if (k <= 0.5) {
        var rxCrescent = Math.max(0.01, r * (1 - (2 * k)));
        return moon_crescent_path(cx, cy, r, rxCrescent, waxing);
    }

    var darkPortion = 1 - k;
    var rxDark = Math.max(0.01, r * (1 - (2 * darkPortion)));
    var darkOnRight = !waxing;
    var cutoutPath = moon_crescent_path(cx, cy, r, rxDark, darkOnRight);

    // Even-odd fill creates a gibbous shape by subtracting the dark crescent.
    return moon_full_disc_path(cx, cy, r) + " " + cutoutPath;
}

function render_oriented_moon_svg(illuminationFraction, waxing, orientationDeg) {
    var cx = 20;
    var cy = 20;
    var r = 17;
    var litPath = moon_illuminated_path(illuminationFraction, waxing, cx, cy, r);
    var litFillRule = illuminationFraction > 0.5 && illuminationFraction < 1 ? "evenodd" : "nonzero";

    var isDarkTheme = jQuery("body").hasClass("dark") || sessionStorage.getItem('currentTheme') === 'dark';
    var moonDark = isDarkTheme ? "#6b7280" : "#8b95a5";
    var moonLight = isDarkTheme ? "#e5ebf7" : "#f6f8fc";
    var moonEdge = isDarkTheme ? "#cbd5e1" : "#6b7280";

    var svg = "";
    svg += "<svg class='moon-phase-svg' viewBox='0 0 40 40' width='40' height='40' aria-hidden='true' focusable='false'>";
    svg += "<g transform='rotate(" + orientationDeg.toFixed(2) + " 20 20)'>";
    svg += "<circle cx='" + cx + "' cy='" + cy + "' r='" + r + "' fill='" + moonDark + "'></circle>";
    if (litPath) {
        svg += "<path d='" + litPath + "' fill='" + moonLight + "' fill-rule='" + litFillRule + "'></path>";
    }
    svg += "<circle cx='" + cx + "' cy='" + cy + "' r='" + r + "' fill='none' stroke='" + moonEdge + "' stroke-width='0.8'></circle>";
    svg += "</g>";
    svg += "</svg>";

    return svg;
}

function render_moon_icon_html(data) {
    var almanac = data && data["almanac"];
    var moon = almanac && almanac["moon"];
    var illumination = moon_illumination_fraction(moon);
    var templateTilt = moon_tilt_template_degrees();
    var templateTiltRotation = moon_tilt_to_icon_rotation(templateTilt);
    var litDirection = 0;

    if (templateTiltRotation !== null) {
        litDirection = templateTiltRotation;
    }

    if (illumination === null || litDirection === null) {
        return moon_icon(moon && moon["moon_index"]);
    }

    // Keep shape model fixed to "bright on right", then rotate using
    // ephemeris-derived illuminated-direction angle.
    return render_oriented_moon_svg(illumination, true, litDirection);
}

