}

//  function removes weekdays from forecast_1hr & _3hr labels except at day changes
function forecast_time(i, interval, daytime, showDay) {
    if ((daytime.indexOf(" ") == -1) || (interval == "forecast_24hr")) return daytime;
    var strday = daytime.substr(0, daytime.indexOf(" "));
    var strtime = daytime.substr(daytime.indexOf(" ") + 1);

    if (interval == "forecast_1hr" || interval == "forecast_3hr") {
        if (showDay) {
            return strtime + '<br><span class="forecast-rollover-day">' + strday + '</span>';
        }
        return strtime;
    }

    return daytime;
}

