    }

    if (ws <= 1) {
        return 0
    } else if (ws <= 3) {
        return 1
    } else if (ws <= 6) {
        return 2
    } else if (ws <= 10) {
        return 3
    } else if (ws <= 15) {
        return 4
    } else if (ws <= 21) {
        return 5
    } else if (ws <= 27) {
        return 6
    } else if (ws <= 33) {
        return 7
    } else if (ws <= 40) {
        return 8
    } else if (ws <= 47) {
        return 9
    } else if (ws <= 55) {
        return 10
    } else if (ws <= 63) {
        return 11
    } else {
        return 12
    }
}

